class NoteBook:
    def __init__(self, path):
        self.path = os.path.abspath(path)
        self.zk_dir = os.path.join(self.path, ".zk")
        self.db_path = os.path.join(self.zk_dir, "notebook.db")
        self.config_path = os.path.join(self.zk_dir, "config.toml")
