    def init_db_schema(self, conn):
        cur = conn.cursor()
        cur.execute("""
            CREATE TABLE IF NOT EXISTS notes (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                path TEXT NOT NULL,
                sortable_path TEXT NOT NULL,
                title TEXT DEFAULT('') NOT NULL,
                lead TEXT DEFAULT('') NOT NULL,
                body TEXT DEFAULT('') NOT NULL,
                raw_content TEXT DEFAULT('') NOT NULL,
                word_count INTEGER DEFAULT(0) NOT NULL,
                checksum TEXT NOT NULL,
                created DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,
                modified DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,
                metadata TEXT DEFAULT('{}') NOT NULL,
                filename TEXT DEFAULT('') NOT NULL,
                UNIQUE(path)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS links (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                source_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
                target_id INTEGER REFERENCES notes(id) ON DELETE SET NULL,
                title TEXT DEFAULT('') NOT NULL,
                href TEXT NOT NULL,
                external INT DEFAULT(0) NOT NULL,
                rels TEXT DEFAULT('') NOT NULL,
                snippet TEXT DEFAULT('') NOT NULL,
                snippet_start INTEGER DEFAULT(0) NOT NULL,
                snippet_end INTEGER DEFAULT(0) NOT NULL,
                type TEXT DEFAULT('') NOT NULL
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS collections (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                kind TEXT NOT NULL,
                name TEXT NOT NULL,
                UNIQUE(kind, name)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS notes_collections (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
                collection_id INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS metadata (
                key TEXT PRIMARY KEY NOT NULL,
                value TEXT NOT NULL
            )
        """)
        cur.execute("INSERT OR IGNORE INTO metadata (key, value) VALUES ('zk.reindexing_required', 'false')")

        try:
            cur.execute("""
                CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
                    path, title, body,
                    content = notes,
                    content_rowid = id,
                    tokenize = "porter unicode61 remove_diacritics 1 tokenchars '''&/'"
                )
            """)
        except Exception:
            pass
        conn.commit()

    def index(self, verbose=False, force=False, quiet=False):
        conn = self.get_db()
        cur = conn.cursor()

        scanned_files = {}
        for root, dirs, files in os.walk(self.path):
            if ".zk" in dirs:
                dirs.remove(".zk")
            dirs[:] = [d for d in dirs if not d.startswith(".")]

            for file in files:
                if file.endswith(".md") and not file.startswith("."):
                    abs_p = os.path.join(root, file)
                    rel_p = os.path.relpath(abs_p, self.path)
                    scanned_files[rel_p] = abs_p

        existing_notes = {}
        for row in cur.execute("SELECT id, path, checksum FROM notes"):
            existing_notes[row["path"]] = (row["id"], row["checksum"])

        added = 0
        modified = 0
        removed = 0
        unchanged = 0

        for rel_p, (nid, _) in list(existing_notes.items()):
            if rel_p not in scanned_files:
                cur.execute("DELETE FROM notes WHERE id=?", (nid,))
                cur.execute("DELETE FROM links WHERE source_id=?", (nid,))
                cur.execute("DELETE FROM notes_collections WHERE note_id=?", (nid,))
                removed += 1
                if verbose:
                    print(f"- removed {rel_p}")

        conn.commit()

        for rel_p in sorted(scanned_files.keys()):
            abs_p = scanned_files[rel_p]
            with open(abs_p, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()

            checksum = hashlib.sha256(content.encode("utf-8")).hexdigest()
            st = os.stat(abs_p)
            mtime_dt = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).isoformat()
            ctime_dt = datetime.fromtimestamp(st.st_ctime, tz=timezone.utc).isoformat()

            if rel_p in existing_notes and not force:
                old_id, old_chk = existing_notes[rel_p]
                if old_chk == checksum:
                    unchanged += 1
                    if verbose:
                        print(f"- unchanged {rel_p}")
                    continue
                else:
                    is_new = False
                    modified += 1
                    if verbose:
                        print(f"- modified {rel_p}")
            else:
                is_new = True
                added += 1
                if verbose:
                    print(f"- added {rel_p}")

            meta, body = parse_yaml_frontmatter(content)

            title = meta.get("title", "")
            if not title:
                m_h = re.search(r'^\s*#\s+(.+)$', content, re.MULTILINE)
                if m_h:
                    title = m_h.group(1).strip()
            if isinstance(title, list):
                title = title[0] if title else ""
            title = str(title)

            words = body.split()
            word_count = len(words)

            body_lines = [line.strip() for line in body.splitlines() if line.strip()]
            lead = body_lines[0] if body_lines else ""
            if meta and lead.startswith("---"):
                lead = ""

            c_date = meta.get("created") or ctime_dt
            m_date = meta.get("modified") or mtime_dt
            c_date_iso = parse_iso_date(str(c_date))
            if c_date_iso:
                c_date = c_date_iso.isoformat()
            m_date_iso = parse_iso_date(str(m_date))
            if m_date_iso:
                m_date = m_date_iso.isoformat()

            meta_json = json.dumps(meta)
            filename = os.path.basename(rel_p)

            if is_new:
                cur.execute("""
                    INSERT INTO notes (path, sortable_path, title, lead, body, raw_content, word_count, checksum, created, modified, metadata, filename)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (rel_p, rel_p, title, lead, body, content, word_count, checksum, c_date, m_date, meta_json, filename))
                nid = cur.lastrowid
            else:
                nid = old_id
                cur.execute("""
                    UPDATE notes SET sortable_path=?, title=?, lead=?, body=?, raw_content=?, word_count=?, checksum=?, created=?, modified=?, metadata=?, filename=?
                    WHERE id=?
                """, (rel_p, title, lead, body, content, word_count, checksum, c_date, m_date, meta_json, filename, nid))

            tags = set()
            meta_tags = meta.get("tags", [])
            if isinstance(meta_tags, str):
                tags.add(meta_tags)
            elif isinstance(meta_tags, list):
                for t in meta_tags:
                    if isinstance(t, str):
                        tags.add(t)

            clean_body = re.sub(r'```[\s\S]*?```', '', body)
            clean_body = re.sub(r'`[^`]+`', '', clean_body)
            for m_t in re.finditer(r'(?:^|\s)#([a-zA-Z_][a-zA-Z0-9_/-]*)', clean_body):
                tag_name = m_t.group(1)
                if not tag_name.isdigit():
                    tags.add(tag_name)

            cur.execute("DELETE FROM notes_collections WHERE note_id=?", (nid,))
            for tag_name in sorted(tags):
                cur.execute("INSERT OR IGNORE INTO collections (kind, name) VALUES ('tag', ?)", (tag_name,))
                cur.execute("SELECT id FROM collections WHERE kind='tag' AND name=?", (tag_name,))
                cid = cur.fetchone()[0]
                cur.execute("INSERT INTO notes_collections (note_id, collection_id) VALUES (?, ?)", (nid, cid))

            cur.execute("DELETE FROM links WHERE source_id=?", (nid,))
            for m_l in re.finditer(r'\[\[([^\]\|]+)(?:\|([^\]]+))?\]\]', body):
                href = m_l.group(1).strip()
                l_title = m_l.group(2).strip() if m_l.group(2) else href
                cur.execute("""
                    INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type)
                    VALUES (?, NULL, ?, ?, 0, '', ?, ?, ?, 'wiki-link')
                """, (nid, l_title, href, body, 0, len(body)))

            for m_m in re.finditer(r'\[([^\]]+)\]\(([^)]+)\)', body):
                l_title = m_m.group(1).strip()
                href = m_m.group(2).strip()
                ext = 1 if href.startswith("http://") or href.startswith("https://") else 0
                cur.execute("""
                    INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type)
                    VALUES (?, NULL, ?, ?, ?, '', ?, ?, ?, 'markdown')
                """, (nid, l_title, href, ext, body, 0, len(body)))

        conn.commit()

        all_notes = list(cur.execute("SELECT id, path, title, filename FROM notes"))
        note_map = {}
        for n in all_notes:
            stem = os.path.splitext(n["filename"])[0]
            note_map[n["path"]] = n["id"]
            note_map[n["filename"]] = n["id"]
            note_map[stem] = n["id"]
            if n["title"]:
                note_map[n["title"]] = n["id"]

        all_links = list(cur.execute("SELECT id, href FROM links WHERE external=0"))
        for l in all_links:
            target_id = note_map.get(l["href"])
            if target_id is not None:
                cur.execute("UPDATE links SET target_id=? WHERE id=?", (target_id, l["id"]))

        conn.commit()
        conn.close()

        if not quiet:
            print(f"Indexed {added + modified + unchanged} notes in 0s\n  + {added} added\n  ~ {modified} modified\n  - {removed} removed")

def find_notebook_root(start_dir, notebook_dir_override=None):
    if notebook_dir_override:
        p = os.path.abspath(notebook_dir_override)
        if os.path.exists(os.path.join(p, ".zk")):
            return p
        return p

    cur = os.path.abspath(start_dir)
    while True:
        if os.path.exists(os.path.join(cur, ".zk")):
            return cur
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    return None

def init_notebook(target_dir, no_input=False):
    target_dir = os.path.abspath(target_dir)
    if not os.path.exists(target_dir):
        os.makedirs(target_dir, exist_ok=True)

    zk_dir = os.path.join(target_dir, ".zk")
    if os.path.exists(zk_dir):
        sys.stderr.write(f"zk: error: init: a notebook already exists in {target_dir}\n")
        sys.exit(1)

    os.makedirs(zk_dir, exist_ok=True)
    os.makedirs(os.path.join(zk_dir, "templates"), exist_ok=True)

    with open(os.path.join(zk_dir, "config.toml"), "w", encoding="utf-8") as f:
        f.write(DEFAULT_CONFIG_TOML)

    with open(os.path.join(zk_dir, "templates", "default.md"), "w", encoding="utf-8") as f:
        f.write(DEFAULT_TEMPLATE_MD)

    nb = NoteBook(target_dir)
    nb.get_db().close()

    print(f"\nInitialized a notebook in {target_dir}")

def query_notes(nb, paths=None, tags=None, tagless=False, orphan=False, missing_backlink=False,
                matches=None, match_strategy="fts", exclude=None, link_to=None, no_link_to=None,
                linked_by=None, no_linked_by=None, mention=None, mentioned_by=None,
                created_before=None, created_after=None, modified_before=None, modified_after=None,
                sort_terms=None, limit=None, max_distance=None, recursive=False):

    # Auto-index first
    nb.index(quiet=True)
    conn = nb.get_db()
    cur = conn.cursor()

    notes = {}
    for r in cur.execute("SELECT * FROM notes"):
        notes[r["id"]] = dict(r)

    # Attach tags
    for nid in notes:
        tag_rows = cur.execute("""
            SELECT c.name FROM collections c
            JOIN notes_collections nc ON c.id=nc.collection_id
            WHERE nc.note_id=? AND c.kind='tag'
            ORDER BY c.name ASC
        """, (nid,)).fetchall()
        notes[nid]["tags"] = [tr["name"] for tr in tag_rows]
        try:
            notes[nid]["metadata"] = json.loads(notes[nid]["metadata"]) if notes[nid]["metadata"] else {}
        except Exception:
            notes[nid]["metadata"] = {}

    links_rows = cur.execute("SELECT * FROM links").fetchall()
    all_links = [dict(lr) for lr in links_rows]

    filtered_ids = set(notes.keys())

    # Filter paths
    if paths:
        path_matches = set()
        for nid, n in notes.items():
            np = n["path"]
            for p in paths:
                p_clean = p.rstrip("/")
                if np == p_clean or np.startswith(p_clean + "/"):
                    path_matches.add(nid)
                    break
        filtered_ids &= path_matches

    # Filter excludes
    if exclude:
        for p in exclude:
            p_clean = p.rstrip("/")
            to_rem = set()
            for nid in filtered_ids:
                np = notes[nid]["path"]
                if np == p_clean or np.startswith(p_clean + "/"):
                    to_rem.add(nid)
            filtered_ids -= to_rem

    # Filter tags
    if tags:
        for t in tags:
            tag_matches = set()
            for nid in filtered_ids:
                if t in notes[nid]["tags"]:
                    tag_matches.add(nid)
            filtered_ids &= tag_matches

    if tagless:
        filtered_ids = {nid for nid in filtered_ids if not notes[nid]["tags"]}

    if orphan:
        # Orphan notes are not linked by any other note
        linked_targets = {l["target_id"] for l in all_links if l["target_id"] is not None and l["source_id"] != l["target_id"]}
        filtered_ids = {nid for nid in filtered_ids if nid not in linked_targets}

    if missing_backlink:
        # Note A links to B, but B does NOT link to A -> B has a missing backlink
        missing_ids = set()
        for l in all_links:
            src = l["source_id"]
            tgt = l["target_id"]
            if tgt is not None and src != tgt:
                # Check if tgt links back to src
                backlink = any(l2["source_id"] == tgt and l2["target_id"] == src for l2 in all_links)
                if not backlink:
                    missing_ids.add(tgt)
        filtered_ids &= missing_ids

    # Filter link_to
    if link_to:
        target_ids = set()
        for lt in link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)

        valid_sources = set()
        if recursive:
            visited = set(target_ids)
            curr = set(target_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["target_id"] in curr and l["source_id"] not in visited:
                        valid_sources.add(l["source_id"])
                        visited.add(l["source_id"])
                        next_curr.add(l["source_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["target_id"] in target_ids:
                    valid_sources.add(l["source_id"])
        filtered_ids &= valid_sources

    if no_link_to:
        target_ids = set()
        for lt in no_link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)
        sources = {l["source_id"] for l in all_links if l["target_id"] in target_ids}
        filtered_ids -= sources

    # Filter linked_by
    if linked_by:
        source_ids = set()
        for lb in linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        valid_targets = set()
        if recursive:
            visited = set(source_ids)
            curr = set(source_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["source_id"] in curr and l["target_id"] is not None and l["target_id"] not in visited:
                        valid_targets.add(l["target_id"])
                        visited.add(l["target_id"])
                        next_curr.add(l["target_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["source_id"] in source_ids and l["target_id"] is not None:
                    valid_targets.add(l["target_id"])
        filtered_ids &= valid_targets

    if no_linked_by:
        source_ids = set()
        for lb in no_linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        targets = {l["target_id"] for l in all_links if l["source_id"] in source_ids and l["target_id"] is not None}
        filtered_ids -= targets

    # Filter mention
    if mention:
        target_titles = set()
        for m in mention:
            for nid, n in notes.items():
                if (n["path"] == m or n["filename"] == m or os.path.splitext(n["filename"])[0] == m) and n["title"]:
                    target_titles.add(n["title"])
        mentioning = set()
        for nid in filtered_ids:
            body = notes[nid]["raw_content"]
            for title in target_titles:
                if title and title in body and not f"[[{title}]]" in body:
                    mentioning.add(nid)
        filtered_ids &= mentioning

    if matches:
        match_ids = set()
        for m in matches:
            for nid in filtered_ids:
                n = notes[nid]
                text = f"{n['title']} {n['body']}"
                if match_strategy == "re":
                    if re.search(m, text, re.IGNORECASE):
                        match_ids.add(nid)
                elif match_strategy == "exact":
                    if m in text:
                        match_ids.add(nid)
                else: # fts / terms
                    terms = m.lower().split()
                    if all(term in text.lower() for term in terms):
                        match_ids.add(nid)
        filtered_ids &= match_ids

    # Date filters
    if created_before:
        dt_cb = parse_iso_date(created_before)
        if dt_cb:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) < dt_cb}
    if created_after:
        dt_ca = parse_iso_date(created_after)
        if dt_ca:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) > dt_ca}

    res = [notes[nid] for nid in filtered_ids]

    # Sorting
    if sort_terms:
        for st in reversed(sort_terms):
            rev = False
            if st.endswith("-"):
                rev = True
                st = st[:-1]
            if st == "title":
                res.sort(key=lambda x: x["title"].lower(), reverse=rev)
            elif st == "path":
                res.sort(key=lambda x: x["path"].lower(), reverse=rev)
            elif st == "created":
                res.sort(key=lambda x: x["created"], reverse=rev)
            elif st == "modified":
                res.sort(key=lambda x: x["modified"], reverse=rev)
            elif st == "word-count":
                res.sort(key=lambda x: x["word_count"], reverse=rev)
            elif st == "random":
                random.shuffle(res)

    if limit and limit > 0:
        res = res[:limit]

    conn.close()
    return res, all_links

def format_note_obj(n, nb):
    abs_path = os.path.join(nb.path, n["path"])
    link_fmt = nb.config.get("format", {}).get("markdown", {}).get("link-format", "wiki")
    stem = os.path.splitext(n["filename"])[0]

    if link_fmt == "markdown":
        title_disp = n["title"] or ""
        link_str = f"[{title_disp}]({stem})"
    else:
        link_str = f"[[{stem}]]"

    snippets = [n["lead"]] if n["lead"] else []

    return {
        "filename": n["filename"],
        "filenameStem": stem,
        "path": n["path"],
        "absPath": abs_path,
        "title": n["title"],
        "link": link_str,
        "lead": n["lead"],
        "body": n["body"],
        "snippets": snippets,
        "rawContent": n["raw_content"],
        "wordCount": n["word_count"],
        "tags": n["tags"],
        "metadata": n["metadata"],
        "created": n["created"],
        "modified": n["modified"],
        "checksum": n["checksum"]
    }

def print_notes_list(notes_list, nb, fmt="short", header=None, footer="\n", delimiter=None, delimiter0=False, quiet=False):
    if not quiet:
        count = len(notes_list)
        sys.stderr.write(f"\nFound {count} note{'s' if count != 1 else ''}\n")

    if header:
        sys.stdout.write(header.replace("\\n", "\n"))

    objs = [format_note_obj(n, nb) for n in notes_list]

    if fmt == "json":
        sys.stdout.write(json.dumps(objs) + "\n")
        return
    elif fmt == "jsonl":
        for o in objs:
            sys.stdout.write(json.dumps(o) + "\n")
        return

    default_delim = "\n" if fmt == "oneline" else "\n\n"
    delim = "\0" if delimiter0 else (delimiter if delimiter is not None else default_delim)

    out_items = []
    for o in objs:
        if fmt == "oneline":
            t = o["title"] or o["path"]
            if not o["title"]:
                item = f" {o['path']} ({format_relative_date(o['modified'])})"
            else:
                item = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})"
        elif fmt == "short":
            head = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})" if o['title'] else f" {o['path']} ({format_relative_date(o['modified'])})"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "medium":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "long":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "full":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}\nTags: {', '.join(o['tags'])}"
            if o["body"]:
                indented_body = "\n".join("  " + line for line in o["body"].splitlines())
                item = f"{head}\n\n{indented_body}"
            else:
                item = head
        else:
            # Custom template format
            item = render_template(fmt, {
                "id": o["filenameStem"],
                "filename": o["filename"],
                "filenameStem": o["filenameStem"],
                "path": o["path"],
                "absPath": o["absPath"],
                "title": o["title"],
                "title-or-path": o["title"] or o["path"],
                "link": o["link"],
                "body": o["body"],
                "lead": o["lead"],
                "rawContent": o["rawContent"],
                "wordCount": o["wordCount"],
                "tags": o["tags"],
                "metadata": o["metadata"],
                "created": o["created"],
                "modified": o["modified"],
                "checksum": o["checksum"]
            })
        out_items.append(item)

    if out_items:
        sys.stdout.write(delim.join(out_items))
        if not delimiter0 and not fmt.startswith("json"):
            sys.stdout.write("\n")

    if footer:
        sys.stdout.write(footer.replace("\\n", "\n"))

def main():
    argv = sys.argv[1:]

    # Pre-parse global flags
    working_dir = None
    notebook_dir = None
    no_input = False
    clean_argv = []

