    if diff < 0:
        diff = 0
    if diff < 60:
        return "just now"
    mins = diff // 60
    if mins < 60:
        return f"{mins} minute{'s' if mins > 1 else ''} ago"
    hours = mins // 60
    if hours < 24:
        return f"{hours} hour{'s' if hours > 1 else ''} ago"
    days = hours // 24
