    if charset == "alphanum":
        chars = string.ascii_letters + string.digits
    elif charset == "letters":
        chars = string.ascii_letters
    elif charset == "numbers":
        chars = string.digits
    elif charset == "hex":
        chars = "0123456789abcdef"
    else:
        chars = charset

    res = ''.join(random.choice(chars) for _ in range(length))
