def parse_yaml_frontmatter(text):
    if not text.startswith("---"):
        return {}, text.strip()
    parts = text.split("---", 2)
    if len(parts) < 3:
        return {}, text.strip()

    yaml_str = parts[1]
    body = parts[2].strip()

