    i = 0
    while i < len(lines):
        line = lines[i]
        if "#" in line:
            line = line.split("#")[0]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue

        if line.startswith("  - ") or line.startswith("- "):
            val = stripped[2:].strip().strip('"\'')
            if current_key:
                if not isinstance(metadata.get(current_key), list):
                    metadata[current_key] = []
                metadata[current_key].append(val)
            i += 1
            continue

        if ":" in line:
            k, v = line.split(":", 1)
            k = k.strip()
            v = v.strip()
            current_key = k
            if not v:
                metadata[k] = []
            elif v.startswith("[") and v.endswith("]"):
                items = [x.strip().strip('"\'') for x in v[1:-1].split(",") if x.strip()]
                metadata[k] = items
            else:
                val = v.strip('"\'')
                metadata[k] = val
        i += 1

    return metadata, body

def slugify(text):
    text = text.lower()
    text = re.sub(r'[^\w\s-]', '', text)
    text = re.sub(r'[\s_]+', '-', text)
    text = text.strip('-')
    return text

def generate_random_id(length=4, charset="alphanum", case="lower"):
    if charset == "alphanum":
        chars = string.ascii_letters + string.digits
    elif charset == "letters":
        chars = string.ascii_letters
    elif charset == "numbers":
        chars = string.digits
    elif charset == "hex":
        chars = "0123456789abcdef"
    else:
        chars = charset

    res = ''.join(random.choice(chars) for _ in range(length))
    if case == "lower":
        res = res.lower()
    elif case == "upper":
        res = res.upper()
    return res

def format_relative_date(dt):
    if dt is None:
        return ""
    now = datetime.now(timezone.utc)
    if isinstance(dt, str):
        dt = parse_iso_date(dt)
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    diff = int((now - dt).total_seconds())
    if diff < 0:
        diff = 0
    if diff < 60:
        return "just now"
    mins = diff // 60
    if mins < 60:
        return f"{mins} minute{'s' if mins > 1 else ''} ago"
    hours = mins // 60
    if hours < 24:
        return f"{hours} hour{'s' if hours > 1 else ''} ago"
    days = hours // 24
    if days < 7:
        return f"{days} day{'s' if days > 1 else ''} ago"
    weeks = days // 7
    if weeks < 4:
        return f"{weeks} week{'s' if weeks > 1 else ''} ago"
    months = days // 30
    if months < 12:
        return f"{months} month{'s' if months > 1 else ''} ago"
    years = days // 365
    return f"{years} year{'s' if years > 1 else ''} ago"

def parse_iso_date(dt_str):
    if not dt_str:
        return None
    dt_str = str(dt_str).strip()
    try:
        if dt_str.endswith("Z"):
            dt_str = dt_str[:-1] + "+00:00"
        return datetime.fromisoformat(dt_str)
    except Exception:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%Y/%m/%d"):
        try:
            return datetime.strptime(dt_str, fmt).replace(tzinfo=timezone.utc)
        except Exception:
            pass
    return None

def to_utc_iso_string(dt):
    if isinstance(dt, str):
        parsed = parse_iso_date(dt)
        if parsed:
            dt = parsed
        else:
            return dt
    if not isinstance(dt, datetime):
        return str(dt)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S.%f") + "Z"

def format_date_val(dt, fmt="short"):
    if isinstance(dt, str):
        parsed = parse_iso_date(dt)
        if parsed:
            dt = parsed
        else:
            return dt
    if not isinstance(dt, datetime):
        return str(dt)

    if fmt == "short":
        return dt.strftime("%m/%d/%Y")
    elif fmt == "medium":
        return dt.strftime("%b %d, %Y")
    elif fmt == "long":
        return dt.strftime("%B %d, %Y")
    elif fmt == "full":
        return dt.strftime("%A, %B %d, %Y")
    elif fmt == "relative":
        return format_relative_date(dt)
    elif fmt.startswith("%"):
        return dt.strftime(fmt)
    else:
        return dt.strftime(fmt)

def render_template(tpl_text, vars_dict):
    def repl_date(m):
        var_name = m.group(1)
        fmt_arg = m.group(2) or "short"
        fmt_arg = fmt_arg.strip('"\'')
        val = vars_dict.get(var_name, "")
        if var_name == "now":
            val = vars_dict.get("now", datetime.now(timezone.utc))
        return format_date_val(val, fmt_arg)

    res = re.sub(r'\{\{\s*format-date\s+([^\s\}]+)(?:\s+"([^"]+)"|\s+\'([^\']+)\')?\s*\}\}', repl_date, tpl_text)

    def repl_slug(m):
        var_name = m.group(1)
        val = vars_dict.get(var_name, "")
        return slugify(str(val))

    res = re.sub(r'\{\{\s*slug\s+([^\s\}]+)\s*\}\}', repl_slug, res)

    def repl_join(m):
        var_name = m.group(1)
        sep = m.group(2) if m.group(2) is not None else m.group(3) or ""
        val = vars_dict.get(var_name, [])
        if isinstance(val, list):
            return sep.join(str(x) for x in val)
        return str(val)

    res = re.sub(r'\{\{\s*join\s+([^\s\}]+)(?:\s+"([^"]+)"|\s+\'([^\']+)\')?\s*\}\}', repl_join, res)

    def repl_var(m):
        v = m.group(1).strip()
        if v.startswith("extra."):
            extra_map = vars_dict.get("extra", {})
            key = v[6:]
            return str(extra_map.get(key, ""))
        val = vars_dict.get(v, "")
        if isinstance(val, list):
            return " ".join(str(x) for x in val)
        if isinstance(val, dict):
            return json.dumps(val, sort_keys=True)
        return str(val)

    res = re.sub(r'\{\{\s*([a-zA-Z0-9_\.-]+)\s*\}\}', repl_var, res)
    return res

class NoteBook:
    def __init__(self, path):
        self.path = os.path.abspath(path)
        self.zk_dir = os.path.join(self.path, ".zk")
        self.db_path = os.path.join(self.zk_dir, "notebook.db")
        self.config_path = os.path.join(self.zk_dir, "config.toml")
        self.config = self.load_config()

    def load_config(self):
        cfg = {
            "note": {
                "template": "default.md",
                "filename": "{{id}}",
                "extension": "md",
                "default-title": "Untitled",
                "id-charset": "alphanum",
                "id-length": 4,
                "id-case": "lower"
            },
            "extra": {},
            "format": {
                "markdown": {
                    "link-format": "wiki",
                    "hashtags": True,
                    "colon-tags": False,
                    "multiword-tags": False
                }
            },
            "tool": {},
            "alias": {},
            "group": {}
        }
        if os.path.exists(self.config_path) and tomli is not None:
            try:
                with open(self.config_path, "rb") as f:
                    loaded = tomli.load(f)
                    for k, v in loaded.items():
                        if k in cfg and isinstance(v, dict):
                            cfg[k].update(v)
                        else:
                            cfg[k] = v
            except Exception:
                pass
        return cfg

    def get_group_config(self, group_name=None, rel_dir=None):
        note_cfg = dict(self.config.get("note", {}))
        extra_cfg = dict(self.config.get("extra", {}))

        groups = self.config.get("group", {})
        target_group = None
        if group_name and group_name in groups:
            target_group = groups[group_name]
        elif rel_dir:
            for g_name, g_val in groups.items():
                paths = g_val.get("paths", [g_name])
                if any(rel_dir == p or rel_dir.startswith(p + "/") for p in paths):
                    target_group = g_val
                    break

        if target_group and isinstance(target_group, dict):
            if "note" in target_group and isinstance(target_group["note"], dict):
                note_cfg.update(target_group["note"])
            if "extra" in target_group and isinstance(target_group["extra"], dict):
                extra_cfg.update(target_group["extra"])

        return note_cfg, extra_cfg

    def get_db(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        self.init_db_schema(conn)
        return conn

    def init_db_schema(self, conn):
        cur = conn.cursor()
        cur.execute("""
            CREATE TABLE IF NOT EXISTS notes (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                path TEXT NOT NULL,
                sortable_path TEXT NOT NULL,
                title TEXT DEFAULT('') NOT NULL,
                lead TEXT DEFAULT('') NOT NULL,
                body TEXT DEFAULT('') NOT NULL,
                raw_content TEXT DEFAULT('') NOT NULL,
                word_count INTEGER DEFAULT(0) NOT NULL,
                checksum TEXT NOT NULL,
                created DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,
                modified DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,
                metadata TEXT DEFAULT('{}') NOT NULL,
                filename TEXT DEFAULT('') NOT NULL,
                UNIQUE(path)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS links (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                source_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
                target_id INTEGER REFERENCES notes(id) ON DELETE SET NULL,
                title TEXT DEFAULT('') NOT NULL,
                href TEXT NOT NULL,
                external INT DEFAULT(0) NOT NULL,
                rels TEXT DEFAULT('') NOT NULL,
                snippet TEXT DEFAULT('') NOT NULL,
                snippet_start INTEGER DEFAULT(0) NOT NULL,
                snippet_end INTEGER DEFAULT(0) NOT NULL,
                type TEXT DEFAULT('') NOT NULL
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS collections (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                kind TEXT NOT NULL,
                name TEXT NOT NULL,
                UNIQUE(kind, name)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS notes_collections (
                id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
                collection_id INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS metadata (
                key TEXT PRIMARY KEY NOT NULL,
                value TEXT NOT NULL
            )
        """)
        cur.execute("INSERT OR IGNORE INTO metadata (key, value) VALUES ('zk.reindexing_required', 'false')")

        try:
            cur.execute("""
                CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
                    path, title, body,
                    content = notes,
                    content_rowid = id,
                    tokenize = "porter unicode61 remove_diacritics 1 tokenchars '''&/'"
                )
            """)
        except Exception:
            pass
        conn.commit()

    def index(self, verbose=False, force=False, quiet=False):
        conn = self.get_db()
        cur = conn.cursor()

        scanned_files = {}
        for root, dirs, files in os.walk(self.path):
            if ".zk" in dirs:
                dirs.remove(".zk")
            dirs[:] = [d for d in dirs if not d.startswith(".")]

            for file in files:
                if file.endswith(".md") and not file.startswith("."):
                    abs_p = os.path.join(root, file)
                    rel_p = os.path.relpath(abs_p, self.path)
                    scanned_files[rel_p] = abs_p

        existing_notes = {}
        for row in cur.execute("SELECT id, path, checksum FROM notes"):
            existing_notes[row["path"]] = (row["id"], row["checksum"])

        added = 0
        modified = 0
        removed = 0
        unchanged = 0

        for rel_p, (nid, _) in list(existing_notes.items()):
            if rel_p not in scanned_files:
                cur.execute("DELETE FROM notes WHERE id=?", (nid,))
                cur.execute("DELETE FROM links WHERE source_id=?", (nid,))
                cur.execute("DELETE FROM notes_collections WHERE note_id=?", (nid,))
                removed += 1
                if verbose:
                    print(f"- removed {rel_p}")

        conn.commit()

        for rel_p in sorted(scanned_files.keys()):
            abs_p = scanned_files[rel_p]
            with open(abs_p, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()

            checksum = hashlib.sha256(content.encode("utf-8")).hexdigest()
            st = os.stat(abs_p)
            mtime_dt = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).isoformat()
            ctime_dt = datetime.fromtimestamp(st.st_ctime, tz=timezone.utc).isoformat()

            if rel_p in existing_notes and not force:
                old_id, old_chk = existing_notes[rel_p]
                if old_chk == checksum:
                    unchanged += 1
                    if verbose:
                        print(f"- unchanged {rel_p}")
                    continue
                else:
                    is_new = False
                    modified += 1
                    if verbose:
                        print(f"- modified {rel_p}")
            else:
                is_new = True
                added += 1
                if verbose:
                    print(f"- added {rel_p}")

            meta, body = parse_yaml_frontmatter(content)

            title = meta.get("title", "")
            if not title:
                m_h = re.search(r'^\s*#\s+(.+)$', content, re.MULTILINE)
                if m_h:
                    title = m_h.group(1).strip()
            if isinstance(title, list):
                title = title[0] if title else ""
            title = str(title)

            word_count = len(content.split())

            body_lines = [line.strip() for line in body.splitlines() if line.strip()]
            lead = body_lines[0] if body_lines else ""
            if meta and lead.startswith("---"):
                lead = ""

            c_date = meta.get("created") or ctime_dt
            m_date = meta.get("modified") or mtime_dt
            c_date_iso = parse_iso_date(str(c_date))
            if c_date_iso:
                c_date = c_date_iso.isoformat()
            m_date_iso = parse_iso_date(str(m_date))
            if m_date_iso:
                m_date = m_date_iso.isoformat()

            meta_json = json.dumps(meta, sort_keys=True)
            filename = os.path.basename(rel_p)

            if is_new:
                cur.execute("""
                    INSERT INTO notes (path, sortable_path, title, lead, body, raw_content, word_count, checksum, created, modified, metadata, filename)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (rel_p, rel_p, title, lead, body, content, word_count, checksum, c_date, m_date, meta_json, filename))
                nid = cur.lastrowid
            else:
                nid = old_id
                cur.execute("""
                    UPDATE notes SET sortable_path=?, title=?, lead=?, body=?, raw_content=?, word_count=?, checksum=?, created=?, modified=?, metadata=?, filename=?
                    WHERE id=?
                """, (rel_p, title, lead, body, content, word_count, checksum, c_date, m_date, meta_json, filename, nid))

            tags = set()
            meta_tags = meta.get("tags", [])
            if isinstance(meta_tags, str):
                tags.add(meta_tags)
            elif isinstance(meta_tags, list):
                for t in meta_tags:
                    if isinstance(t, str):
                        tags.add(t)

            clean_body = re.sub(r'```[\s\S]*?```', '', body)
            clean_body = re.sub(r'`[^`]+`', '', clean_body)
            for m_t in re.finditer(r'(?:^|\s)#([a-zA-Z_][a-zA-Z0-9_/-]*)', clean_body):
                tag_name = m_t.group(1)
                if not tag_name.isdigit():
                    tags.add(tag_name)

            cur.execute("DELETE FROM notes_collections WHERE note_id=?", (nid,))
            for tag_name in sorted(tags):
                cur.execute("INSERT OR IGNORE INTO collections (kind, name) VALUES ('tag', ?)", (tag_name,))
                cur.execute("SELECT id FROM collections WHERE kind='tag' AND name=?", (tag_name,))
                cid = cur.fetchone()[0]
                cur.execute("INSERT INTO notes_collections (note_id, collection_id) VALUES (?, ?)", (nid, cid))

            cur.execute("DELETE FROM links WHERE source_id=?", (nid,))
            # Find snippet offsets in raw_content
            for m_l in re.finditer(r'\[\[([^\]\|]+)(?:\|([^\]]+))?\]\]', body):
                href = m_l.group(1).strip()
                l_title = m_l.group(2).strip() if m_l.group(2) else href

                # Snippet range in raw_content
                link_str = m_l.group(0)
                pos = content.find(link_str)
                if pos != -1:
                    para_start = content.rfind("\n\n", 0, pos)
                    para_start = para_start + 2 if para_start != -1 else 0
                    para_end = content.find("\n\n", pos)
                    para_end = para_end if para_end != -1 else len(content)
                    snip_text = content[para_start:para_end].strip()
                    snip_start = para_start
                    snip_end = para_end
                else:
                    snip_text = body
                    snip_start = 0
                    snip_end = len(content)

                cur.execute("""
                    INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type)
                    VALUES (?, NULL, ?, ?, 0, '', ?, ?, ?, 'wiki-link')
                """, (nid, l_title, href, snip_text, snip_start, snip_end))

            for m_m in re.finditer(r'\[([^\]]+)\]\(([^)]+)\)', body):
                l_title = m_m.group(1).strip()
                href = m_m.group(2).strip()
                ext = 1 if href.startswith("http://") or href.startswith("https://") else 0

                link_str = m_m.group(0)
                pos = content.find(link_str)
                if pos != -1:
                    para_start = content.rfind("\n\n", 0, pos)
                    para_start = para_start + 2 if para_start != -1 else 0
                    para_end = content.find("\n\n", pos)
                    para_end = para_end if para_end != -1 else len(content)
                    snip_text = content[para_start:para_end].strip()
                    snip_start = para_start
                    snip_end = para_end
                else:
                    snip_text = body
                    snip_start = 0
                    snip_end = len(content)

                cur.execute("""
                    INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type)
                    VALUES (?, NULL, ?, ?, ?, '', ?, ?, ?, 'markdown')
                """, (nid, l_title, href, ext, snip_text, snip_start, snip_end))

        conn.commit()

        all_notes = list(cur.execute("SELECT id, path, title, filename FROM notes"))
        note_map = {}
        for n in all_notes:
            stem = os.path.splitext(n["filename"])[0]
            note_map[n["path"]] = n["id"]
            note_map[n["filename"]] = n["id"]
            note_map[stem] = n["id"]
            if n["title"]:
                note_map[n["title"]] = n["id"]

        all_links = list(cur.execute("SELECT id, href FROM links WHERE external=0"))
        for l in all_links:
            target_id = note_map.get(l["href"])
            if target_id is not None:
                cur.execute("UPDATE links SET target_id=? WHERE id=?", (target_id, l["id"]))

        conn.commit()
        conn.close()

        if not quiet:
            print(f"Indexed {added + modified + unchanged} notes in 0s\n  + {added} added\n  ~ {modified} modified\n  - {removed} removed")

def find_notebook_root(start_dir, notebook_dir_override=None):
    if notebook_dir_override:
        p = os.path.abspath(notebook_dir_override)
        if os.path.exists(os.path.join(p, ".zk")):
            return p
        return p

    cur = os.path.abspath(start_dir)
    while True:
        if os.path.exists(os.path.join(cur, ".zk")):
            return cur
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    return None

def init_notebook(target_dir, no_input=False):
    target_dir = os.path.abspath(target_dir)
    zk_dir = os.path.join(target_dir, ".zk")
    if os.path.exists(zk_dir):
        sys.stderr.write(f"zk: error: init: a notebook already exists in {target_dir}\n")
        sys.exit(1)

    os.makedirs(target_dir, exist_ok=True)
    os.makedirs(zk_dir, exist_ok=True)
    os.makedirs(os.path.join(zk_dir, "templates"), exist_ok=True)

    with open(os.path.join(zk_dir, "config.toml"), "w", encoding="utf-8") as f:
        f.write(DEFAULT_CONFIG_TOML)

    with open(os.path.join(zk_dir, "templates", "default.md"), "w", encoding="utf-8") as f:
        f.write(DEFAULT_TEMPLATE_MD)

    nb = NoteBook(target_dir)
    nb.get_db().close()

    print(f"\nInitialized a notebook in {target_dir}")

def query_notes(nb, paths=None, tags=None, tagless=False, orphan=False, missing_backlink=False,
                matches=None, match_strategy="fts", exclude=None, link_to=None, no_link_to=None,
                linked_by=None, no_linked_by=None, mention=None, mentioned_by=None,
                created_before=None, created_after=None, modified_before=None, modified_after=None,
                sort_terms=None, limit=None, max_distance=None, recursive=False):

    nb.index(quiet=True)
    conn = nb.get_db()
    cur = conn.cursor()

    notes = {}
    for r in cur.execute("SELECT * FROM notes"):
        notes[r["id"]] = dict(r)

    for nid in notes:
        tag_rows = cur.execute("""
            SELECT c.name FROM collections c
            JOIN notes_collections nc ON c.id=nc.collection_id
            WHERE nc.note_id=? AND c.kind='tag'
            ORDER BY c.name ASC
        """, (nid,)).fetchall()
        notes[nid]["tags"] = [tr["name"] for tr in tag_rows]
        try:
            notes[nid]["metadata"] = json.loads(notes[nid]["metadata"]) if notes[nid]["metadata"] else {}
        except Exception:
            notes[nid]["metadata"] = {}

    links_rows = cur.execute("SELECT * FROM links").fetchall()
    all_links = [dict(lr) for lr in links_rows]

    filtered_ids = set(notes.keys())

    if paths:
        path_matches = set()
        for nid, n in notes.items():
            np = n["path"]
            for p in paths:
                p_clean = p.rstrip("/")
                if np == p_clean or np.startswith(p_clean + "/"):
                    path_matches.add(nid)
                    break
        filtered_ids &= path_matches

    if exclude:
        for p in exclude:
            p_clean = p.rstrip("/")
            to_rem = set()
            for nid in filtered_ids:
                np = notes[nid]["path"]
                if np == p_clean or np.startswith(p_clean + "/"):
                    to_rem.add(nid)
            filtered_ids -= to_rem

    if tags:
        for t in tags:
            tag_matches = set()
            for nid in filtered_ids:
                if t in notes[nid]["tags"]:
                    tag_matches.add(nid)
            filtered_ids &= tag_matches

    if tagless:
        filtered_ids = {nid for nid in filtered_ids if not notes[nid]["tags"]}

    if orphan:
        linked_targets = {l["target_id"] for l in all_links if l["target_id"] is not None and l["source_id"] != l["target_id"]}
        filtered_ids = {nid for nid in filtered_ids if nid not in linked_targets}

    if missing_backlink:
        missing_ids = set()
        for l in all_links:
            src = l["source_id"]
            tgt = l["target_id"]
            if tgt is not None and src != tgt:
                backlink = any(l2["source_id"] == tgt and l2["target_id"] == src for l2 in all_links)
                if not backlink:
                    missing_ids.add(tgt)
        filtered_ids &= missing_ids

    if link_to:
        target_ids = set()
        for lt in link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)

        valid_sources = set()
        if recursive:
            visited = set(target_ids)
            curr = set(target_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["target_id"] in curr and l["source_id"] not in visited:
                        valid_sources.add(l["source_id"])
                        visited.add(l["source_id"])
                        next_curr.add(l["source_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["target_id"] in target_ids:
                    valid_sources.add(l["source_id"])
        filtered_ids &= valid_sources

    if no_link_to:
        target_ids = set()
        for lt in no_link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)
        sources = {l["source_id"] for l in all_links if l["target_id"] in target_ids}
        filtered_ids -= sources

    if linked_by:
        source_ids = set()
        for lb in linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        valid_targets = set()
        if recursive:
            visited = set(source_ids)
            curr = set(source_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["source_id"] in curr and l["target_id"] is not None and l["target_id"] not in visited:
                        valid_targets.add(l["target_id"])
                        visited.add(l["target_id"])
                        next_curr.add(l["target_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["source_id"] in source_ids and l["target_id"] is not None:
                    valid_targets.add(l["target_id"])
        filtered_ids &= valid_targets

    if no_linked_by:
        source_ids = set()
        for lb in no_linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        targets = {l["target_id"] for l in all_links if l["source_id"] in source_ids and l["target_id"] is not None}
        filtered_ids -= targets

    if mention:
        target_titles = set()
        for m in mention:
            for nid, n in notes.items():
                if (n["path"] == m or n["filename"] == m or os.path.splitext(n["filename"])[0] == m) and n["title"]:
                    target_titles.add(n["title"])
        mentioning = set()
        for nid in filtered_ids:
            body = notes[nid]["raw_content"]
            for title in target_titles:
                if title and title in body and not f"[[{title}]]" in body:
                    mentioning.add(nid)
        filtered_ids &= mentioning

    if matches:
        match_ids = set()
        for m in matches:
            for nid in filtered_ids:
                n = notes[nid]
                text = f"{n['title']} {n['body']}"
                if match_strategy == "re":
                    if re.search(m, text, re.IGNORECASE):
                        match_ids.add(nid)
                elif match_strategy == "exact":
                    if m in text:
                        match_ids.add(nid)
                else:
                    terms = m.lower().split()
                    if all(term in text.lower() for term in terms):
                        match_ids.add(nid)
        filtered_ids &= match_ids

    if created_before:
        dt_cb = parse_iso_date(created_before)
        if dt_cb:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) < dt_cb}
    if created_after:
        dt_ca = parse_iso_date(created_after)
        if dt_ca:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) > dt_ca}

    res = [notes[nid] for nid in filtered_ids]

    if sort_terms:
        for st in reversed(sort_terms):
            rev = False
            if st.endswith("-"):
                rev = True
                st = st[:-1]
            if st == "title":
                res.sort(key=lambda x: x["title"].lower(), reverse=rev)
            elif st == "path":
                res.sort(key=lambda x: x["path"].lower(), reverse=rev)
            elif st == "created":
                res.sort(key=lambda x: x["created"], reverse=rev)
            elif st == "modified":
                res.sort(key=lambda x: x["modified"], reverse=rev)
            elif st == "word-count":
                res.sort(key=lambda x: x["word_count"], reverse=rev)
            elif st == "random":
                random.shuffle(res)

    if limit and limit > 0:
        res = res[:limit]

    conn.close()
    return res, all_links

def format_note_obj(n, nb):
    abs_path = os.path.join(nb.path, n["path"])
    link_fmt = nb.config.get("format", {}).get("markdown", {}).get("link-format", "wiki")
    stem = os.path.splitext(n["filename"])[0]

    if link_fmt == "markdown":
        title_disp = n["title"] or ""
        link_str = f"[{title_disp}]({stem})"
    else:
        link_str = f"[[{stem}]]"

    snippets = [n["lead"]] if n["lead"] else []

    # Sort metadata dict keys
    meta = n["metadata"]
    if isinstance(meta, dict):
        sorted_meta = {k: meta[k] for k in sorted(meta.keys())}
    else:
        sorted_meta = meta

    return {
        "filename": n["filename"],
        "filenameStem": stem,
        "path": n["path"],
        "absPath": abs_path,
        "title": n["title"],
        "link": link_str,
        "lead": n["lead"],
        "body": n["body"],
        "snippets": snippets,
        "rawContent": n["raw_content"],
        "wordCount": n["word_count"],
        "tags": n["tags"],
        "metadata": sorted_meta,
        "created": to_utc_iso_string(n["created"]),
        "modified": to_utc_iso_string(n["modified"]),
        "checksum": n["checksum"]
    }

def print_notes_list(notes_list, nb, fmt="short", header=None, footer="\n", delimiter=None, delimiter0=False, quiet=False):
    if not quiet:
        count = len(notes_list)
        sys.stderr.write(f"\nFound {count} note{'s' if count > 1 else ''}\n")

    if header:
        sys.stdout.write(header.replace("\\n", "\n"))

    objs = [format_note_obj(n, nb) for n in notes_list]

    if fmt == "json":
        sys.stdout.write(json.dumps(objs) + "\n")
        return
    elif fmt == "jsonl":
        for o in objs:
            sys.stdout.write(json.dumps(o) + "\n")
        return

    default_delim = "\n" if fmt == "oneline" else "\n\n"
    delim = "\0" if delimiter0 else (delimiter if delimiter is not None else default_delim)

    out_items = []
    for o in objs:
        if fmt == "oneline":
            if not o["title"]:
                item = f" {o['path']} ({format_relative_date(o['modified'])})"
            else:
                item = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})"
        elif fmt == "short":
            head = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})" if o['title'] else f" {o['path']} ({format_relative_date(o['modified'])})"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "medium":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "long":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "full":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}\nTags: {', '.join(o['tags'])}"
            if o["body"]:
                indented_body = "\n".join("  " + line for line in o["body"].splitlines())
                item = f"{head}\n\n{indented_body}"
            else:
                item = head
        else:
            item = render_template(fmt, {
                "id": o["filenameStem"],
                "filename": o["filename"],
                "filenameStem": o["filenameStem"],
                "path": o["path"],
                "absPath": o["absPath"],
                "title": o["title"],
                "title-or-path": o["title"] or o["path"],
                "link": o["link"],
                "body": o["body"],
                "lead": o["lead"],
                "rawContent": o["rawContent"],
                "wordCount": o["wordCount"],
                "tags": o["tags"],
                "metadata": o["metadata"],
                "created": o["created"],
                "modified": o["modified"],
                "checksum": o["checksum"]
            })
        out_items.append(item)

    if out_items:
        sys.stdout.write(delim.join(out_items) + delim)

    if footer and footer != "\n":
        sys.stdout.write(footer.replace("\\n", "\n"))

def main():
    argv = sys.argv[1:]

    working_dir = None
    notebook_dir = None
    no_input = False
    clean_argv = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg.startswith("-W="):
            working_dir = arg.split("=", 1)[1]
        elif arg == "-W" or arg == "--working-dir":
            i += 1
            if i < len(argv):
                working_dir = argv[i]
        elif arg.startswith("--working-dir="):
            working_dir = arg.split("=", 1)[1]
        elif arg.startswith("--notebook-dir="):
            notebook_dir = arg.split("=", 1)[1]
        elif arg == "--notebook-dir":
            i += 1
            if i < len(argv):
                notebook_dir = argv[i]
        elif arg == "--no-input":
            no_input = True
        elif arg in ("--version", "-v") and len(argv) == 1:
            print("zk dev")
            sys.exit(0)
        else:
            clean_argv.append(arg)
        i += 1

    if working_dir:
        os.chdir(working_dir)

    cwd = os.getcwd()

    if not clean_argv or clean_argv[0] in ("-h", "--help"):
        print("""Usage: zk <command>

Commands:

NOTEBOOK
  init     Create a new notebook in the given directory.
  index    Index the notes to be searchable.

NOTES
  new      Create a new note in the given notebook directory.
  list     List notes matching the given criteria.
  graph    Produce a graph of the notes matching the given criteria.
  edit     Edit notes matching the given criteria.
  tag      Manage the note tags.

Flags:
  -h, --help                 Show context-sensitive help.
      --notebook-dir=PATH    Turn off notebook auto-discovery and set manually
                             the notebook where commands are run.
  -W, --working-dir=PATH     Run as if zk was started in <PATH> instead of the
                             current working directory.
      --no-input             Never prompt or ask for confirmation.

Run "zk <command> --help" for more information on a command.""")
        sys.exit(0)

    cmd = clean_argv[0]

    if cmd == "init":
        target = clean_argv[1] if len(clean_argv) > 1 and not clean_argv[1].startswith("-") else "."
        init_notebook(target, no_input=no_input)
        sys.exit(0)

    nb_root = find_notebook_root(cwd, notebook_dir)
    if not nb_root:
        sys.stderr.write(f"zk: error: failed to open notebook: no notebook found in {cwd} or a parent directory\n")
        sys.exit(1)

    nb = NoteBook(nb_root)

    if cmd == "index":
        verbose = "-v" in clean_argv or "--verbose" in clean_argv
        force = "-f" in clean_argv or "--force" in clean_argv
        quiet = "-q" in clean_argv or "--quiet" in clean_argv
        nb.index(verbose=verbose, force=force, quiet=quiet)
        sys.exit(0)

    if cmd == "new":
        title = ""
        date_str = None
        group_name = None
        extra_vars = {}
        tpl_path = None
        print_path = False
        dry_run = False
        custom_id = None
        interactive = False
        target_dir = ""

        idx = 1
        while idx < len(clean_argv):
            a = clean_argv[idx]
            if a in ("-p", "--print-path"):
                print_path = True
            elif a in ("-n", "--dry-run"):
                dry_run = True
            elif a in ("-i", "--interactive"):
                interactive = True
            elif a.startswith("-t=") or a.startswith("--title="):
                title = a.split("=", 1)[1]
            elif a in ("-t", "--title"):
                idx += 1
                title = clean_argv[idx]
            elif a.startswith("--date="):
                date_str = a.split("=", 1)[1]
            elif a.startswith("--id="):
                custom_id = a.split("=", 1)[1]
            elif a.startswith("-g=") or a.startswith("--group="):
                group_name = a.split("=", 1)[1]
            elif a in ("-g", "--group"):
                idx += 1
                group_name = clean_argv[idx]
            elif a.startswith("--template="):
                tpl_path = a.split("=", 1)[1]
            elif a.startswith("--extra="):
                for kv in a.split("=", 1)[1].split(","):
                    if "=" in kv:
                        k, v = kv.split("=", 1)
                        extra_vars[k.strip()] = v.strip()
            elif not a.startswith("-"):
                target_dir = a
            idx += 1

        rel_target_dir = target_dir.rstrip("/")
        full_target_dir = os.path.join(nb.path, rel_target_dir) if rel_target_dir else nb.path
        if rel_target_dir and not os.path.exists(full_target_dir):
            sys.stderr.write(f"zk: error: new note: {target_dir}: directory not found\n")
            sys.exit(1)

        note_cfg, extra_cfg = nb.get_group_config(group_name, rel_target_dir)
        extra_cfg.update(extra_vars)

        now_dt = parse_iso_date(date_str) if date_str else datetime.now(timezone.utc)
        note_id = custom_id if custom_id else generate_random_id(
            length=int(note_cfg.get("id-length", 4)),
            charset=note_cfg.get("id-charset", "alphanum"),
            case=note_cfg.get("id-case", "lower")
        )

        ext = note_cfg.get("extension", "md")

        tpl_name = tpl_path or note_cfg.get("template", "default.md")
        if os.path.isabs(tpl_name):
            full_tpl_path = tpl_name
        else:
            full_tpl_path = os.path.join(nb.zk_dir, "templates", tpl_name)

        if os.path.exists(full_tpl_path):
            with open(full_tpl_path, "r", encoding="utf-8") as f:
                tpl_text = f.read()
        else:
            tpl_text = DEFAULT_TEMPLATE_MD

        content_in = ""
        if interactive:
            content_in = sys.stdin.read().strip()

        fn_tpl = note_cfg.get("filename", "{{id}}")
        fn_vars = {
            "id": note_id,
            "title": title,
            "extension": ext,
            "now": now_dt,
            "date": format_date_val(now_dt, "short"),
            "extra": extra_cfg
        }
        fn_rendered = render_template(fn_tpl, fn_vars)
        if not fn_rendered.endswith("." + ext):
            fn_rendered += "." + ext

        note_rel_path = os.path.join(rel_target_dir, fn_rendered) if rel_target_dir else fn_rendered
        note_abs_path = os.path.join(nb.path, note_rel_path)

        tpl_vars = {
            "id": note_id,
            "title": title,
            "content": content_in,
            "extension": ext,
            "filename": fn_rendered,
            "now": now_dt,
            "date": format_date_val(now_dt, "short"),
            "extra": extra_cfg
        }
        rendered_content = render_template(tpl_text, tpl_vars)

        if dry_run:
            sys.stdout.write(rendered_content)
            if not rendered_content.endswith("\n"):
                sys.stdout.write("\n")
            sys.stderr.write(note_abs_path + "\n")
            sys.exit(0)

        with open(note_abs_path, "w", encoding="utf-8") as f:
            f.write(rendered_content)

        nb.index(quiet=True)

        if print_path:
            print(note_abs_path)
            sys.exit(0)

        editor = os.environ.get("EDITOR") or os.environ.get("VISUAL") or nb.config.get("tool", {}).get("editor") or "vim"
        subprocess.run(f'{editor} "{note_abs_path}"', shell=True)
        sys.exit(0)

    paths = []
    tags = []
    tagless = False
    orphan = False
    missing_backlink = False
    matches = []
    match_strategy = "fts"
    exclude = []
    link_to = []
    no_link_to = []
    linked_by = []
    no_linked_by = []
    mention = []
    created_before = None
    created_after = None
    modified_before = None
    modified_after = None
    sort_terms = []
    limit = None
    fmt = "short" if cmd == "list" else "full"
    header = None
    footer = "\n"
    delimiter = None
    delimiter0 = False
    quiet = False
    recursive = False

    if cmd == "graph":
        fmt = ""

    idx = 1
    if cmd == "tag":
        if len(clean_argv) > 1 and clean_argv[1] == "list":
            cmd = "tag list"
            idx = 2

    while idx < len(clean_argv):
        a = clean_argv[idx]
        if a.startswith("-f=") or a.startswith("--format="):
            fmt = a.split("=", 1)[1]
        elif a in ("-f", "--format"):
            idx += 1
            fmt = clean_argv[idx]
        elif a.startswith("-s=") or a.startswith("--sort="):
            sort_terms = a.split("=", 1)[1].split(",")
        elif a in ("-s", "--sort"):
            idx += 1
            sort_terms = clean_argv[idx].split(",")
        elif a.startswith("-n=") or a.startswith("--limit="):
            limit = int(a.split("=", 1)[1])
        elif a in ("-n", "--limit"):
            idx += 1
            limit = int(clean_argv[idx])
        elif a.startswith("-t=") or a.startswith("--tag="):
            tags.extend(a.split("=", 1)[1].split(","))
        elif a in ("-t", "--tag"):
            idx += 1
            tags.extend(clean_argv[idx].split(","))
        elif a == "--tagless":
            tagless = True
        elif a == "--orphan":
            orphan = True
        elif a == "--missing-backlink":
            missing_backlink = True
        elif a in ("-r", "--recursive"):
            recursive = True
        elif a.startswith("-m=") or a.startswith("--match="):
            matches.extend(a.split("=", 1)[1].split(","))
        elif a in ("-m", "--match"):
            idx += 1
            matches.extend(clean_argv[idx].split(","))
        elif a.startswith("-M=") or a.startswith("--match-strategy="):
            match_strategy = a.split("=", 1)[1]
        elif a.startswith("-x=") or a.startswith("--exclude="):
            exclude.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("-l=") or a.startswith("--link-to="):
            link_to.extend(a.split("=", 1)[1].split(","))
        elif a in ("-l", "--link-to"):
            idx += 1
            link_to.extend(clean_argv[idx].split(","))
        elif a.startswith("--no-link-to="):
            no_link_to.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("-L=") or a.startswith("--linked-by="):
            linked_by.extend(a.split("=", 1)[1].split(","))
        elif a in ("-L", "--linked-by"):
            idx += 1
            linked_by.extend(clean_argv[idx].split(","))
        elif a.startswith("--no-linked-by="):
            no_linked_by.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("--mention="):
            mention.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("--created-before="):
            created_before = a.split("=", 1)[1]
        elif a.startswith("--created-after="):
            created_after = a.split("=", 1)[1]
        elif a.startswith("--header="):
            header = a.split("=", 1)[1]
        elif a.startswith("--footer="):
            footer = a.split("=", 1)[1]
        elif a.startswith("-d=") or a.startswith("--delimiter="):
            delimiter = a.split("=", 1)[1]
        elif a in ("-d", "--delimiter"):
            idx += 1
            delimiter = clean_argv[idx]
        elif a in ("-0", "--delimiter0"):
            delimiter0 = True
        elif a in ("-q", "--quiet"):
            quiet = True
        elif not a.startswith("-"):
            paths.append(a)
        idx += 1

    if cmd == "graph" and not fmt:
        sys.stderr.write("zk: error: missing flags: --format=STRING\n")
        sys.exit(1)

    if cmd == "tag list":
        nb.index(quiet=True)
        conn = nb.get_db()
        cur = conn.cursor()
        rows = cur.execute("""
            SELECT c.id, c.kind, c.name, COUNT(nc.note_id) as noteCount
            FROM collections c
            JOIN notes_collections nc ON c.id=nc.collection_id
            WHERE c.kind='tag'
            GROUP BY c.id
        """).fetchall()

        tag_list = [dict(r) for r in rows]
        if sort_terms:
            for st in reversed(sort_terms):
                rev = False
                if st.endswith("-"):
                    rev = True
                    st = st[:-1]
                if st == "name":
                    tag_list.sort(key=lambda x: x["name"].lower(), reverse=rev)
                elif st == "note-count":
                    tag_list.sort(key=lambda x: x["noteCount"], reverse=rev)
        else:
            tag_list.sort(key=lambda x: x["name"].lower())

        if not quiet:
            count = len(tag_list)
            sys.stderr.write(f"\nFound {count} tag{'s' if count > 1 else ''}\n")

        if fmt == "name":
            for t in tag_list:
                print(t["name"])
        elif fmt == "full":
            for t in tag_list:
                print(f"{t['name']} ({t['noteCount']})")
        elif fmt == "json":
            print(json.dumps(tag_list))
        elif fmt == "jsonl":
            for t in tag_list:
                print(json.dumps(t))
        else:
            for t in tag_list:
                print(render_template(fmt, t))
        sys.exit(0)

    notes_res, all_links = query_notes(
        nb, paths=paths, tags=tags, tagless=tagless, orphan=orphan, missing_backlink=missing_backlink,
        matches=matches, match_strategy=match_strategy, exclude=exclude, link_to=link_to,
        no_link_to=no_link_to, linked_by=linked_by, no_linked_by=no_linked_by, mention=mention,
        created_before=created_before, created_after=created_after, modified_before=modified_before,
        modified_after=modified_after, sort_terms=sort_terms, limit=limit, recursive=recursive
    )

    if cmd == "list":
        print_notes_list(notes_res, nb, fmt=fmt, header=header, footer=footer, delimiter=delimiter, delimiter0=delimiter0, quiet=quiet)
        sys.exit(0)

    elif cmd == "graph":
        note_objs = [format_note_obj(n, nb) for n in notes_res]
        note_ids = {n["id"] for n in notes_res}
        note_id_to_path = {n["id"]: n["path"] for n in notes_res}

        graph_links = []
        for l in all_links:
            if l["source_id"] in note_ids and l["target_id"] in note_ids:
                graph_links.append({
                    "title": l["title"],
                    "href": l["href"],
                    "type": l["type"],
                    "isExternal": bool(l["external"]),
