def parse_yaml_frontmatter(text):
    if not text.startswith("---"):
        return {}, text.strip()
    parts = text.split("---", 2)
    if len(parts) < 3:
        return {}, text.strip()

    yaml_str = parts[1]
    body = parts[2].strip()

    metadata = {}
    current_key = None

    lines = yaml_str.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        if "#" in line:
            line = line.split("#")[0]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue

        if line.startswith("  - ") or line.startswith("- "):
            val = stripped[2:].strip().strip('"\'')
            if current_key:
                if not isinstance(metadata.get(current_key), list):
                    metadata[current_key] = []
                metadata[current_key].append(val)
            i += 1
            continue

        if ":" in line:
            k, v = line.split(":", 1)
            k = k.strip()
            v = v.strip()
            current_key = k
            if not v:
                metadata[k] = []
            elif v.startswith("[") and v.endswith("]"):
                items = [x.strip().strip('"\'') for x in v[1:-1].split(",") if x.strip()]
                metadata[k] = items
            else:
                val = v.strip('"\'')
                metadata[k] = val
        i += 1

