    for nid in notes:
        tag_rows = cur.execute("""
            SELECT c.name FROM collections c
            JOIN notes_collections nc ON c.id=nc.collection_id
            WHERE nc.note_id=? AND c.kind='tag'
            ORDER BY c.name ASC
        """, (nid,)).fetchall()
        notes[nid]["tags"] = [tr["name"] for tr in tag_rows]
        try:
            notes[nid]["metadata"] = json.loads(notes[nid]["metadata"]) if notes[nid]["metadata"] else {}
        except Exception:
            notes[nid]["metadata"] = {}

    links_rows = cur.execute("SELECT * FROM links").fetchall()
    all_links = [dict(lr) for lr in links_rows]

    filtered_ids = set(notes.keys())

    if paths:
        path_matches = set()
        for nid, n in notes.items():
            np = n["path"]
            for p in paths:
                p_clean = p.rstrip("/")
                if np == p_clean or np.startswith(p_clean + "/"):
                    path_matches.add(nid)
                    break
        filtered_ids &= path_matches

    if exclude:
        for p in exclude:
            p_clean = p.rstrip("/")
            to_rem = set()
            for nid in filtered_ids:
                np = notes[nid]["path"]
                if np == p_clean or np.startswith(p_clean + "/"):
                    to_rem.add(nid)
            filtered_ids -= to_rem

    if tags:
        for t in tags:
            tag_matches = set()
            for nid in filtered_ids:
                if t in notes[nid]["tags"]:
                    tag_matches.add(nid)
            filtered_ids &= tag_matches

    if tagless:
        filtered_ids = {nid for nid in filtered_ids if not notes[nid]["tags"]}

    if orphan:
        linked_targets = {l["target_id"] for l in all_links if l["target_id"] is not None and l["source_id"] != l["target_id"]}
        filtered_ids = {nid for nid in filtered_ids if nid not in linked_targets}

    if missing_backlink:
        missing_ids = set()
        for l in all_links:
            src = l["source_id"]
            tgt = l["target_id"]
            if tgt is not None and src != tgt:
                backlink = any(l2["source_id"] == tgt and l2["target_id"] == src for l2 in all_links)
                if not backlink:
                    missing_ids.add(tgt)
        filtered_ids &= missing_ids

    if link_to:
        target_ids = set()
        for lt in link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)

        valid_sources = set()
        if recursive:
            visited = set(target_ids)
            curr = set(target_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["target_id"] in curr and l["source_id"] not in visited:
                        valid_sources.add(l["source_id"])
                        visited.add(l["source_id"])
                        next_curr.add(l["source_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["target_id"] in target_ids:
                    valid_sources.add(l["source_id"])
        filtered_ids &= valid_sources

    if no_link_to:
        target_ids = set()
        for lt in no_link_to:
            for nid, n in notes.items():
                if n["path"] == lt or n["filename"] == lt or os.path.splitext(n["filename"])[0] == lt:
                    target_ids.add(nid)
        sources = {l["source_id"] for l in all_links if l["target_id"] in target_ids}
        filtered_ids -= sources

    if linked_by:
        source_ids = set()
        for lb in linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        valid_targets = set()
        if recursive:
            visited = set(source_ids)
            curr = set(source_ids)
            while curr:
                next_curr = set()
                for l in all_links:
                    if l["source_id"] in curr and l["target_id"] is not None and l["target_id"] not in visited:
                        valid_targets.add(l["target_id"])
                        visited.add(l["target_id"])
                        next_curr.add(l["target_id"])
                curr = next_curr
        else:
            for l in all_links:
                if l["source_id"] in source_ids and l["target_id"] is not None:
                    valid_targets.add(l["target_id"])
        filtered_ids &= valid_targets

    if no_linked_by:
        source_ids = set()
        for lb in no_linked_by:
            for nid, n in notes.items():
                if n["path"] == lb or n["filename"] == lb or os.path.splitext(n["filename"])[0] == lb:
                    source_ids.add(nid)
        targets = {l["target_id"] for l in all_links if l["source_id"] in source_ids and l["target_id"] is not None}
        filtered_ids -= targets

    if mention:
        target_titles = set()
        for m in mention:
            for nid, n in notes.items():
                if (n["path"] == m or n["filename"] == m or os.path.splitext(n["filename"])[0] == m) and n["title"]:
                    target_titles.add(n["title"])
        mentioning = set()
        for nid in filtered_ids:
            body = notes[nid]["raw_content"]
            for title in target_titles:
                if title and title in body and not f"[[{title}]]" in body:
                    mentioning.add(nid)
        filtered_ids &= mentioning

    if matches:
        match_ids = set()
        for m in matches:
            for nid in filtered_ids:
                n = notes[nid]
                text = f"{n['title']} {n['body']}"
                if match_strategy == "re":
                    if re.search(m, text, re.IGNORECASE):
                        match_ids.add(nid)
                elif match_strategy == "exact":
                    if m in text:
                        match_ids.add(nid)
                else:
                    terms = m.lower().split()
                    if all(term in text.lower() for term in terms):
                        match_ids.add(nid)
        filtered_ids &= match_ids

    if created_before:
        dt_cb = parse_iso_date(created_before)
        if dt_cb:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) < dt_cb}
    if created_after:
        dt_ca = parse_iso_date(created_after)
        if dt_ca:
            filtered_ids = {nid for nid in filtered_ids if parse_iso_date(notes[nid]["created"]) and parse_iso_date(notes[nid]["created"]) > dt_ca}

    res = [notes[nid] for nid in filtered_ids]

    if sort_terms:
        for st in reversed(sort_terms):
            rev = False
            if st.endswith("-"):
                rev = True
                st = st[:-1]
            if st == "title":
                res.sort(key=lambda x: x["title"].lower(), reverse=rev)
            elif st == "path":
                res.sort(key=lambda x: x["path"].lower(), reverse=rev)
            elif st == "created":
                res.sort(key=lambda x: x["created"], reverse=rev)
            elif st == "modified":
                res.sort(key=lambda x: x["modified"], reverse=rev)
            elif st == "word-count":
                res.sort(key=lambda x: x["word_count"], reverse=rev)
            elif st == "random":
                random.shuffle(res)

    if limit and limit > 0:
        res = res[:limit]

    conn.close()
    return res, all_links

def format_note_obj(n, nb):
    abs_path = os.path.join(nb.path, n["path"])
    link_fmt = nb.config.get("format", {}).get("markdown", {}).get("link-format", "wiki")
    stem = os.path.splitext(n["filename"])[0]

    if link_fmt == "markdown":
        title_disp = n["title"] or ""
        link_str = f"[{title_disp}]({stem})"
    else:
        link_str = f"[[{stem}]]"

    snippets = [n["lead"]] if n["lead"] else []

    # Sort metadata dict keys
    meta = n["metadata"]
    if isinstance(meta, dict):
        sorted_meta = {k: meta[k] for k in sorted(meta.keys())}
    else:
        sorted_meta = meta

    return {
        "filename": n["filename"],
        "filenameStem": stem,
        "path": n["path"],
        "absPath": abs_path,
        "title": n["title"],
        "link": link_str,
        "lead": n["lead"],
        "body": n["body"],
        "snippets": snippets,
        "rawContent": n["raw_content"],
        "wordCount": n["word_count"],
        "tags": n["tags"],
        "metadata": sorted_meta,
        "created": to_utc_iso_string(n["created"]),
        "modified": to_utc_iso_string(n["modified"]),
        "checksum": n["checksum"]
    }

def print_notes_list(notes_list, nb, fmt="short", header=None, footer="\n", delimiter=None, delimiter0=False, quiet=False):
    if not quiet:
        count = len(notes_list)
        sys.stderr.write(f"\nFound {count} note{'s' if count > 1 else ''}\n")

    if header:
        sys.stdout.write(header.replace("\\n", "\n"))

    objs = [format_note_obj(n, nb) for n in notes_list]

    if fmt == "json":
        sys.stdout.write(json.dumps(objs) + "\n")
        return
    elif fmt == "jsonl":
        for o in objs:
            sys.stdout.write(json.dumps(o) + "\n")
        return

    default_delim = "\n" if fmt == "oneline" else "\n\n"
    delim = "\0" if delimiter0 else (delimiter if delimiter is not None else default_delim)

    out_items = []
    for o in objs:
        if fmt == "oneline":
            if not o["title"]:
                item = f" {o['path']} ({format_relative_date(o['modified'])})"
            else:
                item = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})"
        elif fmt == "short":
            head = f"{o['title']} {o['path']} ({format_relative_date(o['modified'])})" if o['title'] else f" {o['path']} ({format_relative_date(o['modified'])})"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "medium":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "long":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}" if o['title'] else f" {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}"
            if o["lead"]:
                indented_lead = "\n".join("  - " + line if idx == 0 else "    " + line for idx, line in enumerate(o["lead"].splitlines()))
                item = f"{head}\n\n{indented_lead}"
            else:
                item = head
        elif fmt == "full":
            head = f"{o['title']} {o['path']}\nCreated: {format_date_val(o['created'], 'short')}\nModified: {format_date_val(o['modified'], 'short')}\nTags: {', '.join(o['tags'])}"
            if o["body"]:
                indented_body = "\n".join("  " + line for line in o["body"].splitlines())
                item = f"{head}\n\n{indented_body}"
            else:
                item = head
        else:
            item = render_template(fmt, {
                "id": o["filenameStem"],
                "filename": o["filename"],
                "filenameStem": o["filenameStem"],
                "path": o["path"],
                "absPath": o["absPath"],
                "title": o["title"],
                "title-or-path": o["title"] or o["path"],
                "link": o["link"],
                "body": o["body"],
                "lead": o["lead"],
                "rawContent": o["rawContent"],
                "wordCount": o["wordCount"],
                "tags": o["tags"],
                "metadata": o["metadata"],
                "created": o["created"],
                "modified": o["modified"],
                "checksum": o["checksum"]
            })
        out_items.append(item)

    if out_items:
        sys.stdout.write(delim.join(out_items) + delim)

    if footer and footer != "\n":
        sys.stdout.write(footer.replace("\\n", "\n"))

def main():
    argv = sys.argv[1:]

    working_dir = None
    notebook_dir = None
    no_input = False
    clean_argv = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg.startswith("-W="):
            working_dir = arg.split("=", 1)[1]
        elif arg == "-W" or arg == "--working-dir":
            i += 1
            if i < len(argv):
                working_dir = argv[i]
        elif arg.startswith("--working-dir="):
            working_dir = arg.split("=", 1)[1]
        elif arg.startswith("--notebook-dir="):
            notebook_dir = arg.split("=", 1)[1]
        elif arg == "--notebook-dir":
            i += 1
            if i < len(argv):
                notebook_dir = argv[i]
        elif arg == "--no-input":
            no_input = True
        elif arg in ("--version", "-v") and len(argv) == 1:
            print("zk dev")
            sys.exit(0)
        else:
            clean_argv.append(arg)
        i += 1

    if working_dir:
        os.chdir(working_dir)

    cwd = os.getcwd()

    if not clean_argv or clean_argv[0] in ("-h", "--help"):
        print("""Usage: zk <command>

Commands:

NOTEBOOK
  init     Create a new notebook in the given directory.
  index    Index the notes to be searchable.

NOTES
  new      Create a new note in the given notebook directory.
  list     List notes matching the given criteria.
  graph    Produce a graph of the notes matching the given criteria.
  edit     Edit notes matching the given criteria.
  tag      Manage the note tags.

Flags:
  -h, --help                 Show context-sensitive help.
      --notebook-dir=PATH    Turn off notebook auto-discovery and set manually
                             the notebook where commands are run.
  -W, --working-dir=PATH     Run as if zk was started in <PATH> instead of the
                             current working directory.
      --no-input             Never prompt or ask for confirmation.

Run "zk <command> --help" for more information on a command.""")
        sys.exit(0)

    cmd = clean_argv[0]

    if cmd == "init":
        target = clean_argv[1] if len(clean_argv) > 1 and not clean_argv[1].startswith("-") else "."
        init_notebook(target, no_input=no_input)
        sys.exit(0)

    nb_root = find_notebook_root(cwd, notebook_dir)
    if not nb_root:
        sys.stderr.write(f"zk: error: failed to open notebook: no notebook found in {cwd} or a parent directory\n")
        sys.exit(1)

    nb = NoteBook(nb_root)

    if cmd == "index":
        verbose = "-v" in clean_argv or "--verbose" in clean_argv
        force = "-f" in clean_argv or "--force" in clean_argv
        quiet = "-q" in clean_argv or "--quiet" in clean_argv
        nb.index(verbose=verbose, force=force, quiet=quiet)
        sys.exit(0)

    if cmd == "new":
        title = ""
        date_str = None
        group_name = None
        extra_vars = {}
        tpl_path = None
        print_path = False
        dry_run = False
        custom_id = None
        interactive = False
        target_dir = ""

        idx = 1
        while idx < len(clean_argv):
            a = clean_argv[idx]
            if a in ("-p", "--print-path"):
                print_path = True
            elif a in ("-n", "--dry-run"):
                dry_run = True
            elif a in ("-i", "--interactive"):
                interactive = True
            elif a.startswith("-t=") or a.startswith("--title="):
                title = a.split("=", 1)[1]
            elif a in ("-t", "--title"):
                idx += 1
                title = clean_argv[idx]
            elif a.startswith("--date="):
                date_str = a.split("=", 1)[1]
            elif a.startswith("--id="):
                custom_id = a.split("=", 1)[1]
            elif a.startswith("-g=") or a.startswith("--group="):
                group_name = a.split("=", 1)[1]
            elif a in ("-g", "--group"):
                idx += 1
                group_name = clean_argv[idx]
            elif a.startswith("--template="):
                tpl_path = a.split("=", 1)[1]
            elif a.startswith("--extra="):
                for kv in a.split("=", 1)[1].split(","):
                    if "=" in kv:
                        k, v = kv.split("=", 1)
                        extra_vars[k.strip()] = v.strip()
            elif not a.startswith("-"):
                target_dir = a
            idx += 1

        rel_target_dir = target_dir.rstrip("/")
        full_target_dir = os.path.join(nb.path, rel_target_dir) if rel_target_dir else nb.path
        if rel_target_dir and not os.path.exists(full_target_dir):
            sys.stderr.write(f"zk: error: new note: {target_dir}: directory not found\n")
            sys.exit(1)

        note_cfg, extra_cfg = nb.get_group_config(group_name, rel_target_dir)
        extra_cfg.update(extra_vars)

        now_dt = parse_iso_date(date_str) if date_str else datetime.now(timezone.utc)
        note_id = custom_id if custom_id else generate_random_id(
            length=int(note_cfg.get("id-length", 4)),
            charset=note_cfg.get("id-charset", "alphanum"),
            case=note_cfg.get("id-case", "lower")
        )

        ext = note_cfg.get("extension", "md")

        tpl_name = tpl_path or note_cfg.get("template", "default.md")
        if os.path.isabs(tpl_name):
            full_tpl_path = tpl_name
        else:
            full_tpl_path = os.path.join(nb.zk_dir, "templates", tpl_name)

        if os.path.exists(full_tpl_path):
            with open(full_tpl_path, "r", encoding="utf-8") as f:
                tpl_text = f.read()
        else:
            tpl_text = DEFAULT_TEMPLATE_MD

        content_in = ""
        if interactive:
            content_in = sys.stdin.read().strip()

        fn_tpl = note_cfg.get("filename", "{{id}}")
        fn_vars = {
            "id": note_id,
            "title": title,
            "extension": ext,
            "now": now_dt,
            "date": format_date_val(now_dt, "short"),
            "extra": extra_cfg
        }
        fn_rendered = render_template(fn_tpl, fn_vars)
        if not fn_rendered.endswith("." + ext):
            fn_rendered += "." + ext

        note_rel_path = os.path.join(rel_target_dir, fn_rendered) if rel_target_dir else fn_rendered
        note_abs_path = os.path.join(nb.path, note_rel_path)

        tpl_vars = {
            "id": note_id,
            "title": title,
            "content": content_in,
            "extension": ext,
            "filename": fn_rendered,
            "now": now_dt,
            "date": format_date_val(now_dt, "short"),
            "extra": extra_cfg
        }
        rendered_content = render_template(tpl_text, tpl_vars)

        if dry_run:
            sys.stdout.write(rendered_content)
            if not rendered_content.endswith("\n"):
                sys.stdout.write("\n")
            sys.stderr.write(note_abs_path + "\n")
            sys.exit(0)

        with open(note_abs_path, "w", encoding="utf-8") as f:
            f.write(rendered_content)

        nb.index(quiet=True)

        if print_path:
            print(note_abs_path)
            sys.exit(0)

        editor = os.environ.get("EDITOR") or os.environ.get("VISUAL") or nb.config.get("tool", {}).get("editor") or "vim"
        subprocess.run(f'{editor} "{note_abs_path}"', shell=True)
        sys.exit(0)

    paths = []
    tags = []
    tagless = False
    orphan = False
    missing_backlink = False
    matches = []
    match_strategy = "fts"
    exclude = []
    link_to = []
    no_link_to = []
    linked_by = []
    no_linked_by = []
    mention = []
    created_before = None
    created_after = None
    modified_before = None
    modified_after = None
    sort_terms = []
    limit = None
    fmt = "short" if cmd == "list" else "full"
    header = None
    footer = "\n"
    delimiter = None
    delimiter0 = False
    quiet = False
    recursive = False

    if cmd == "graph":
        fmt = ""

    idx = 1
    if cmd == "tag":
        if len(clean_argv) > 1 and clean_argv[1] == "list":
            cmd = "tag list"
            idx = 2

    while idx < len(clean_argv):
        a = clean_argv[idx]
        if a.startswith("-f=") or a.startswith("--format="):
            fmt = a.split("=", 1)[1]
        elif a in ("-f", "--format"):
            idx += 1
            fmt = clean_argv[idx]
        elif a.startswith("-s=") or a.startswith("--sort="):
            sort_terms = a.split("=", 1)[1].split(",")
        elif a in ("-s", "--sort"):
            idx += 1
            sort_terms = clean_argv[idx].split(",")
        elif a.startswith("-n=") or a.startswith("--limit="):
            limit = int(a.split("=", 1)[1])
        elif a in ("-n", "--limit"):
            idx += 1
            limit = int(clean_argv[idx])
        elif a.startswith("-t=") or a.startswith("--tag="):
            tags.extend(a.split("=", 1)[1].split(","))
        elif a in ("-t", "--tag"):
            idx += 1
            tags.extend(clean_argv[idx].split(","))
        elif a == "--tagless":
            tagless = True
        elif a == "--orphan":
            orphan = True
        elif a == "--missing-backlink":
            missing_backlink = True
        elif a in ("-r", "--recursive"):
            recursive = True
        elif a.startswith("-m=") or a.startswith("--match="):
            matches.extend(a.split("=", 1)[1].split(","))
        elif a in ("-m", "--match"):
            idx += 1
            matches.extend(clean_argv[idx].split(","))
        elif a.startswith("-M=") or a.startswith("--match-strategy="):
            match_strategy = a.split("=", 1)[1]
        elif a.startswith("-x=") or a.startswith("--exclude="):
            exclude.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("-l=") or a.startswith("--link-to="):
            link_to.extend(a.split("=", 1)[1].split(","))
        elif a in ("-l", "--link-to"):
            idx += 1
            link_to.extend(clean_argv[idx].split(","))
        elif a.startswith("--no-link-to="):
            no_link_to.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("-L=") or a.startswith("--linked-by="):
            linked_by.extend(a.split("=", 1)[1].split(","))
        elif a in ("-L", "--linked-by"):
            idx += 1
            linked_by.extend(clean_argv[idx].split(","))
        elif a.startswith("--no-linked-by="):
            no_linked_by.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("--mention="):
            mention.extend(a.split("=", 1)[1].split(","))
        elif a.startswith("--created-before="):
            created_before = a.split("=", 1)[1]
        elif a.startswith("--created-after="):
            created_after = a.split("=", 1)[1]
        elif a.startswith("--header="):
            header = a.split("=", 1)[1]
        elif a.startswith("--footer="):
            footer = a.split("=", 1)[1]
        elif a.startswith("-d=") or a.startswith("--delimiter="):
            delimiter = a.split("=", 1)[1]
        elif a in ("-d", "--delimiter"):
            idx += 1
            delimiter = clean_argv[idx]
        elif a in ("-0", "--delimiter0"):
            delimiter0 = True
        elif a in ("-q", "--quiet"):
            quiet = True
        elif not a.startswith("-"):
            paths.append(a)
        idx += 1

    if cmd == "graph" and not fmt:
        sys.stderr.write("zk: error: missing flags: --format=STRING\n")
        sys.exit(1)

    if cmd == "tag list":
        nb.index(quiet=True)
        conn = nb.get_db()
        cur = conn.cursor()
        rows = cur.execute("""
            SELECT c.id, c.kind, c.name, COUNT(nc.note_id) as noteCount
            FROM collections c
            JOIN notes_collections nc ON c.id=nc.collection_id
            WHERE c.kind='tag'
            GROUP BY c.id
        """).fetchall()

        tag_list = [dict(r) for r in rows]
        if sort_terms:
            for st in reversed(sort_terms):
                rev = False
                if st.endswith("-"):
                    rev = True
                    st = st[:-1]
                if st == "name":
                    tag_list.sort(key=lambda x: x["name"].lower(), reverse=rev)
                elif st == "note-count":
                    tag_list.sort(key=lambda x: x["noteCount"], reverse=rev)
        else:
            tag_list.sort(key=lambda x: x["name"].lower())

        if not quiet:
            count = len(tag_list)
            sys.stderr.write(f"\nFound {count} tag{'s' if count > 1 else ''}\n")

        if fmt == "name":
            for t in tag_list:
                print(t["name"])
        elif fmt == "full":
            for t in tag_list:
                print(f"{t['name']} ({t['noteCount']})")
        elif fmt == "json":
            print(json.dumps(tag_list))
        elif fmt == "jsonl":
            for t in tag_list:
                print(json.dumps(t))
        else:
            for t in tag_list:
                print(render_template(fmt, t))
        sys.exit(0)

    notes_res, all_links = query_notes(
        nb, paths=paths, tags=tags, tagless=tagless, orphan=orphan, missing_backlink=missing_backlink,
        matches=matches, match_strategy=match_strategy, exclude=exclude, link_to=link_to,
        no_link_to=no_link_to, linked_by=linked_by, no_linked_by=no_linked_by, mention=mention,
        created_before=created_before, created_after=created_after, modified_before=modified_before,
        modified_after=modified_after, sort_terms=sort_terms, limit=limit, recursive=recursive
    )

    if cmd == "list":
        print_notes_list(notes_res, nb, fmt=fmt, header=header, footer=footer, delimiter=delimiter, delimiter0=delimiter0, quiet=quiet)
        sys.exit(0)

    elif cmd == "graph":
        note_objs = [format_note_obj(n, nb) for n in notes_res]
        note_ids = {n["id"] for n in notes_res}
        note_id_to_path = {n["id"]: n["path"] for n in notes_res}

        graph_links = []
        for l in all_links:
            if l["source_id"] in note_ids and l["target_id"] in note_ids:
                graph_links.append({
                    "title": l["title"],
                    "href": l["href"],
                    "type": l["type"],
                    "isExternal": bool(l["external"]),
                    "rels": [],
                    "snippet": l["snippet"],
                    "snippetStart": l["snippet_start"],
                    "snippetEnd": l["snippet_end"],
                    "sourceId": l["source_id"],
                    "sourcePath": note_id_to_path[l["source_id"]],
                    "targetId": l["target_id"],
                    "targetPath": note_id_to_path[l["target_id"]]
                })

        if not quiet:
            count = len(notes_res)
            sys.stderr.write(f"\nFound {count} note{'s' if count > 1 else ''}\n")

        notes_json = ",\n    ".join(json.dumps(n, separators=(',', ':')) for n in note_objs)
        links_json = ",\n    ".join(json.dumps(l, separators=(',', ':')) for l in graph_links)

        sys.stdout.write("{\n  \"notes\": [\n    " + notes_json + "\n  ],\n  \"links\": [\n    " + links_json + "\n  ]\n}\n")
        sys.exit(0)

    elif cmd == "edit":
        if not notes_res:
            print("Found 0 notes.")
            sys.exit(0)

        note_paths = [os.path.join(nb.path, n["path"]) for n in notes_res]
        paths_arg = " ".join(f'"{p}"' for p in note_paths)
        editor = os.environ.get("EDITOR") or os.environ.get("VISUAL") or nb.config.get("tool", {}).get("editor") or "vim"
        subprocess.run(f'{editor} {paths_arg}', shell=True)
        sys.exit(0)

if __name__ == "__main__":
    main()
EOF"}

